CREATE TABLE IF NOT EXISTS schema_migrations(version int PRIMARY KEY);
CREATE TABLE employees(id bigserial PRIMARY KEY, telegram_id bigint UNIQUE NOT NULL, role text NOT NULL CHECK(role IN ('EMPLOYEE','ADMIN')), is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers(id bigserial PRIMARY KEY, telegram_id bigint UNIQUE NOT NULL, phone text UNIQUE NOT NULL, card_token text UNIQUE NOT NULL, referral_token text UNIQUE NOT NULL, referred_by bigint REFERENCES customers(id), consent_version text NOT NULL, consent_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), CHECK(referred_by <> id));
CREATE TABLE loyalty_accounts(customer_id bigint PRIMARY KEY REFERENCES customers(id), balance bigint NOT NULL DEFAULT 0, reserved_balance bigint NOT NULL DEFAULT 0 CHECK(reserved_balance>=0), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(balance>=reserved_balance));
CREATE TABLE loyalty_settings(id int PRIMARY KEY CHECK(id=1), cashback_percent int NOT NULL CHECK(cashback_percent BETWEEN 0 AND 100), max_redemption_percent int NOT NULL CHECK(max_redemption_percent BETWEEN 0 AND 100), referral_reward bigint NOT NULL CHECK(referral_reward BETWEEN 0 AND 1000000), referral_enabled boolean NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
INSERT INTO loyalty_settings VALUES(1,5,50,500,true,now());
CREATE TABLE purchases(id text PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers(id), employee_id bigint NOT NULL REFERENCES employees(telegram_id), store_id text NOT NULL DEFAULT 'main', register_id text NOT NULL DEFAULT 'main', receipt_number text, accessories_amount bigint NOT NULL CHECK(accessories_amount BETWEEN 1 AND 100000000), redeemed_amount bigint NOT NULL CHECK(redeemed_amount>=0), paid_amount bigint NOT NULL CHECK(paid_amount>=0), cashback_percent int NOT NULL, status text NOT NULL CHECK(status IN ('draft','requested','reserved','confirmed','cancelled','returned')), expires_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), confirmed_at timestamptz, CHECK(paid_amount=accessories_amount-redeemed_amount), UNIQUE(store_id,register_id,receipt_number));
CREATE TABLE bonus_transactions(id bigserial PRIMARY KEY, customer_id bigint NOT NULL REFERENCES customers(id), purchase_id text REFERENCES purchases(id), amount bigint NOT NULL, type text NOT NULL CHECK(type IN ('cashback','redemption','referral','reversal','adjustment')), status text NOT NULL DEFAULT 'posted', reason text NOT NULL, created_by bigint NOT NULL, reverses_id bigint UNIQUE REFERENCES bonus_transactions(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX unique_purchase_entry ON bonus_transactions(purchase_id,customer_id,type) WHERE type IN ('cashback','redemption','referral');
CREATE INDEX transaction_history ON bonus_transactions(customer_id,id DESC);
CREATE INDEX expiring_purchases ON purchases(expires_at) WHERE status IN ('requested','reserved');
CREATE TABLE referrals(id bigserial PRIMARY KEY, referrer_id bigint NOT NULL REFERENCES customers(id), referred_id bigint UNIQUE NOT NULL REFERENCES customers(id), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','rewarded','reversed')), qualified_purchase_id text REFERENCES purchases(id), rewarded_at timestamptz, CHECK(referrer_id<>referred_id));
CREATE TABLE dialogs(telegram_id bigint PRIMARY KEY, step text NOT NULL, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_log(id bigserial PRIMARY KEY, actor bigint NOT NULL, action text NOT NULL, details text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE outbox(id bigserial PRIMARY KEY, telegram_id bigint NOT NULL, message text NOT NULL, attempts int NOT NULL DEFAULT 0, next_attempt timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE TABLE rate_limits(telegram_id bigint PRIMARY KEY, window_at timestamptz NOT NULL DEFAULT now(), count int NOT NULL DEFAULT 1);
